from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()


class ErrorStringFound(Exception):
    """
      An error string was found in syslog file.
    """
    def __init__(self, msg=None):
        if not msg:
            msg = "An error string was found in syslog"
        logger.error(msg)


class FailedToCaptureEmilLog(Exception):
    pass
